import {
  isPythonBase10IntLiteral,
  parsePythonBase10Int,
  pythonStringRepr,
} from "../parsing/python-int.mjs";

const OPTIONS = [
  {
    name: "--a",
    dest: "a",
    metavar: "A",
    type: "str",
  },
  {
    name: "--b",
    dest: "b",
    metavar: "B",
    type: "int",
  },
  {
    name: "--c",
    dest: "c",
    metavar: "C",
    type: "str",
  },
];

const OPTION_MAP = new Map(OPTIONS.map((option) => [option.name, option]));

export class CliExit extends Error {
  constructor(code, stdoutText = "", stderrText = "") {
    super(code === 0 ? stdoutText : stderrText);
    this.name = "CliExit";
    this.code = code;
    this.stdoutText = stdoutText;
    this.stderrText = stderrText;
  }
}

function basename(filePath) {
  const normalizedPath = filePath.replace(/\\/g, "/");
  const parts = normalizedPath.split("/");
  return parts[parts.length - 1] || filePath;
}

function usageLine(programName) {
  const optionUsage = OPTIONS.map((option) => `${option.name} ${option.metavar}`).join(" ");
  return `usage: ${programName} [-h] ${optionUsage}`;
}

function formatError(programName, message) {
  return `${usageLine(programName)}\n${programName}: error: ${message}\n`;
}

function fail(programName, message) {
  throw new CliExit(2, "", formatError(programName, message));
}

function help(programName) {
  return `${usageLine(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function needsValue(specification, token) {
  if (token === undefined) {
    return true;
  }

  if (!token.startsWith("-") || token === "-") {
    return false;
  }

  if (specification.type === "int" && isPythonBase10IntLiteral(token)) {
    return false;
  }

  return true;
}

function parseOptionValue(programName, specification, rawValue) {
  if (specification.type === "str") {
    return rawValue;
  }

  if (!isPythonBase10IntLiteral(rawValue)) {
    fail(
      programName,
      `argument ${specification.name}: invalid int value: ${pythonStringRepr(rawValue)}`,
    );
  }

  return parsePythonBase10Int(rawValue);
}

export function getProgramName(argv = process.argv) {
  return basename(argv[1] ?? "test4.mjs");
}

export function formatHelp(programName) {
  return help(programName);
}

export function emitCliExit(error) {
  if (!(error instanceof CliExit)) {
    throw error;
  }

  if (error.stdoutText.length > 0) {
    process.stdout.write(error.stdoutText);
  }

  if (error.stderrText.length > 0) {
    process.stderr.write(error.stderrText);
  }

  process.exit(error.code);
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = argv.slice(2);
  const values = {};
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === "-h" || token === "--help") {
      throw new CliExit(0, help(programName), "");
    }

    if (token === "--") {
      extras.push(...tokens.slice(index + 1));
      break;
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const specification = OPTION_MAP.get(optionName);

