        const nextToken = tokens[index + 1];
        if (needsValue(specification, nextToken)) {
          fail(programName, `argument ${specification.name}: expected one argument`);
        }

        rawValue = nextToken;
        index += 1;
      }

      values[specification.dest] = parseOptionValue(programName, specification, rawValue);
      continue;
    }

    extras.push(token);
  }

  const missingRequired = OPTIONS.filter(
    (option) => values[option.dest] === undefined,
  ).map((option) => option.name);

  if (missingRequired.length > 0) {
    fail(
      programName,
      `the following arguments are required: ${missingRequired.join(", ")}`,
    );
  }

  if (extras.length > 0) {
    fail(programName, `unrecognized arguments: ${extras.join(" ")}`);
  }

  return values;
}

